/** @file
 *  @brief A string_view wrapper to make telemetry calls easier.
 */
#pragma once
#include "../../carb/cpp/StringView.h"

namespace omni
{
namespace structuredlog
{

/**
 * BasicStringView introduced features that are now part of `carb::cpp::basic_string_view`,
 * It is now an alias for it (and acquires its security guarantees and requirements).
 *
 *  @tparam CharT The char type pointed to by the view.
 *  @tparam Traits The type traits for @p CharT.
 */
template <class CharT, class Traits = std::char_traits<CharT>>
using BasicStringView = carb::cpp::basic_string_view<CharT, Traits>;

/** String view for `char` strings. */
using StringView = BasicStringView<char>;

} // namespace structuredlog
} // namespace omni
